    getLockMember: function(param){
        var selection = this.getSelectionModel().getSelections();

        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});

        if(selection.length > 0) {
            mask.show();

            rest.doRequest(
                rest.getRoute('lock_member', false, 'POST', {
                    scope: this,
                    params: {
                        pks: selection.map(function(item) { return item.get('pk') }),
                        model_name: param
                    },
                    callback: function() {
                        mask.hide();
                        mask = undefined;
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success) {
                            this.getStore().reload();
                            Ext.Msg.show({
                                title: 'Atenção',
                                icon: Ext.Msg.INFO,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                        }
                        else
                            Ext.Msg.show({
                                title: 'Atenção',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                    },
                    failure: function(xhr) {
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Recurso indisponível no momento.'
                        });
                    },
                })
            );
        }
        else Ext.Msg.show({
            'title': 'Atenção',
            'icon': Ext.Msg.ERROR,
            'buttons': Ext.Msg.OK,
            'msg': 'Selecione pelo menos um item.'
        });
    },

