    filterMember: function(){
        var wnd = Ext._create('Ext.Window', {
            title: 'Selecionar Membro',
            modal: true,
            resizable: false,
            width: 450,
            border: false,
            buttons: [
                {
                    text: 'Selecionar',
                    scope: this,
                    handler: function() {
                        var form = wnd.getComponent(0).getForm();

                        if(form.getValues().selecionado)
                            this.setFilterProperty('employee__servidor', form.getValues().selecionado, 1002);
                        else
                            this.removeFilterProperty('employee__servidor', 1002);
                        wnd.destroy();
                    }
                },
                {
                    text: 'Fechar',
                    scope: this,
                    handler: function() {
                        wnd.destroy();
                    }
                }
            ],
            items: Ext._create('Ext.form.FormPanel', {
                frame: true,
                items: [
                    {
                        xtype: "rest-autocompletefield",
                        fieldLabel: "Membro",
                        allowBlank: false,
                        rest: "rh.employee.Restful",
                        hiddenName: 'selecionado',
                        name: "selecionado",
                        emptyText: 'Insira a matrícula ou o nome do Membro',
                        preFilter: [
                            {
                                'property': 'tipo',
                                'value': 'M',
                                'stage': 9999
                            }
                        ],
                    },
                ]
            })
        }).show();
    },

    toggleStatus: function(tipo) {
        if(this._filterStatus.indexOf(tipo) >= 0)
            this._filterStatus.remove(tipo);
        else
            this._filterStatus.push(tipo);

        this.setFilterProperty('status__in', this._filterStatus, 1000);
    },

    toggleStatusPendency: function(tipo) {
        this.type_report = null;
        this.getOpenReportAction().menu.get('pendencias').enable();
        
        if (tipo == 1){
            this.getStore().removeAll();
            this.getStore().baseParams = {};
            
           
            this.addFilterProperty('status', 1, 100, false);
            this.addFilterProperty('pendency_teaching', true, 101);
           
            this.type_report = 1;
        }
        else if (tipo == 2){
            this.getStore().removeAll();
            this.getStore().baseParams = {};

            this.addFilterProperty('status', 1, 100, false);
            this.addFilterProperty('pendency_address', true, 101);

            this.type_report = 2;
        }
        else if (tipo == 3){
            this.getStore().removeAll();
            this.getStore().baseParams = {};

            this.addFilterProperty('status', 1, 100, false);
            this.addFilterProperty('pendency_property', true, 101);
            
            this.type_report = 3;
        }
        else if (tipo == 4){
            this.getStore().removeAll();
            this.getStore().baseParams = {};

            this.addFilterProperty('status', 1, 100, false);
            this.addFilterProperty('pendency_debts', true, 101);

            this.type_report = 4;
        }

    },

